from taf.sw.neat.httpclient.ApiClientLocal import ApiClientLocal
from taf.sw.neat.httpclient.neat_uri import NeatAdminURI
from taf.sw.neat.utils.base64_utils import decode_base64_string, encode_base64_string


class NeatAdminV1(object):
    def __init__(self, conn_details, configuration, access_token):
        self.conn_details = conn_details
        self.configuration = Configuration()
        self.configuration.verify_ssl = False
        self.configuration.host = conn_details.make_configuration_host(original_endpoint=self.configuration.get_host_from_settings(index=None))
        self.configuration.access_token = access_token
        api_client = ApiClient(configuration=self.configuration)
        self.http_api_client = ApiClientLocal(configuration, access_token)

        self.secrets_api = SecretsApi(api_client)
        self.configurations_api = ConfigurationsApi(api_client)

    def get_container_registries_secret(self, raw=True, timeout=60):
        res = self.secrets_api.handler_neat_api_admin_v1_secrets_container_registries_get(skip_deserialization=raw, timeout=timeout)

        return get_return_data(res, raw=raw)['data']

    def update_container_registries_secret(self, uuid, raw=True, timeout=60, **kwargs):
        path_params = {'uuid': uuid}
        patch_body = {"data":{
                          "type":"container-registries",
                          "id":"container-registries",
                          "attributes": kwargs
                          }
                     }

        res = self.secrets_api.update_container_registry_secret(path_params=path_params, body=patch_body,
                                                                skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw=raw)['data']

    def get_configurations(self, raw=True, timeout=60):
        res = self.configurations_api.get_configurations_neat_api_admin_v1_configurations_get(skip_deserialization=raw, timeout=timeout)
        return get_return_data(res, raw)

    def get_switch_admin_secret_parameters(self, raw=True, timeout=60):
        res = self.http_api_client.send_get_request(uri=NeatAdminURI.switch_admin_uri, raw=raw, timeout=timeout)
        res = get_return_data(res, raw=raw)['data']
        for item_key, item_value in res["attributes"].items():
            res["attributes"][item_key] = decode_base64_string(item_value)
        return res

    def update_switch_admin_secret_parameters(self, uuid, raw=True, timeout=60, **kwargs):
        body = {
            "data": {
                "type": "switch-admin",
                "id": uuid,
                "attributes": kwargs
            }
        }
        headers = {"Content-Type": "application/merge-patch+json"}
        for item_key, item_value in body["data"]["attributes"].items():
            body["data"]["attributes"][item_key] = encode_base64_string(item_value)
        res = self.http_api_client.send_patch_request(
            uri=NeatAdminURI.switch_admin_uri + "/" + uuid,
            json=body,
            raw=raw,
            headers=headers,
            timeout=timeout
        )
        return get_return_data(res, raw=raw)

