    def update_registry_namespace_config(self, *, uuid: str, hub_registry_namespace_id: str = "",
                                         seed_registry_namespace_id: str = "", raw=True, timeout=60):
        body = {
            "data": {
                "type": "registry-namespace-config",
                "id": uuid,
                "attributes": {
                    "hubRegistryNamespaceId" : hub_registry_namespace_id,
                    "seedRegistryNamespaceId" : seed_registry_namespace_id
                }
            }
        }
        headers = {"Content-Type": "application/merge-patch+json"}
        res = self.http_api_client.send_patch_request(uri=NeatAdminURI.registry_namespace_config_uri + "/" + uuid,
                                                      json=body, raw=raw, headers=headers, timeout=timeout)
        return get_return_data(res, raw=raw)
